class Solution { fun isEvenOddTree(root:TreeNode?):Boolean{val queue=java.util.ArrayDeque<TreeNode>();queue.add(root!!);var level=0;while(queue.isNotEmpty()){var previous=if(level%2==0)Int.MIN_VALUE else Int.MAX_VALUE;repeat(queue.size){val node=queue.removeFirst();if(level%2==0){if(node.`val`%2==0||node.`val`<=previous)return false}else if(node.`val`%2!=0||node.`val`>=previous)return false;previous=node.`val`;node.left?.let{queue.addLast(it)};node.right?.let{queue.addLast(it)}};level++};return true} }
